import requests
queries=['("primary biliary cirrhosis" OR "primary biliary cholangitis") AND (ursodeoxycholic OR UDCA) AND ("heat shock protein" OR HSP)','ursodeoxycholic acid heat shock protein biliary cirrhosis','primary biliary cirrhosis HSP70 UDCA']
for q in queries:
 u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
 r=requests.get(u,params={'db':'pubmed','term':q,'retmax':15,'retmode':'json'},timeout=20).json()
 ids=r['esearchresult']['idlist']
 print('\nQUERY',q,'COUNT',r['esearchresult']['count'],'IDS',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('pubdate'),x[i].get('title'))
